// Codec parity against the golden corpus the core's own Java encoders wrote at the pinned core commit
// (tests/golden/gateway_frames.inc, regenerated by tests/golden/regen.sh):
//   - every command the gateway encodes is byte-equal to its golden frame;
//   - RegisterSession, which the cluster-tools registrar encodes, is byte-equal for the three registrations the
//     gateway makes (oe-gateway, oe-stream, the treasury lane);
//   - every reply the gateway decodes yields exactly the values the Java encoder was given, field by field;
//   - every template the gateway ignores (sent by the core on a subscribed channel, never read) is counted as ignored,
//     never as refused, and reaches no handler;
//   - every template of the gateway's encode, decode and ignore sets has a golden case (a self-contained check: it runs
//     every case itself, so it passes or fails the same alone or after the others).
// A mismatch prints "golden mismatch <template>".
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <functional>
#include <set>
#include <string>
#include <vector>

#include "Check.h"
#include "WireTestValues.h"
#include "cluster_tools/client/CoreSessionRegistrar.h"
#include "gateway/common/OrderEntry.h"
#include "gateway/common/Wire.h"

namespace {
#include "gateway_frames.inc"
}

using namespace openexchange::gateway;
using namespace openexchange::gateway::wire;
using namespace gwtest::values;

namespace {

void goldenEqual(const char *templateName, const std::vector<std::uint8_t> &golden, const std::uint8_t *got,
    std::size_t gotLength)
{
    if (gotLength == golden.size() && 0 == std::memcmp(golden.data(), got, gotLength))
    {
        return;
    }
    std::size_t at = 0;
    while (at < gotLength && at < golden.size() && golden[at] == got[at])
    {
        at++;
    }
    gwtest::fail(__FILE__, __LINE__,
        std::string("golden mismatch ") + templateName + ": length " + std::to_string(gotLength) + " vs golden " +
            std::to_string(golden.size()) + ", first difference at byte " + std::to_string(at));
}

std::set<std::uint16_t> &covered()
{
    static std::set<std::uint16_t> ids;
    return ids;
}

template<typename Encode>
void commandCase(std::uint16_t id, const std::vector<std::uint8_t> &golden, Encode encode)
{
    covered().insert(id);
    std::uint8_t buffer[256] = {};
    const std::size_t length = encode(buffer, sizeof(buffer));
    CHECK(length <= maxCommandLength());
    goldenEqual(templateName(id), golden, buffer, length);
    // a buffer one byte short of the frame is refused (0), never overrun
    std::vector<std::uint8_t> shortBuffer(golden.size() - 1, 0xEE);
    CHECK_MSG(0 == encode(shortBuffer.data(), shortBuffer.size()),
        std::string(templateName(id)) + " encoded into a buffer shorter than its frame");
}

// Records every call the decoder makes, in order.
struct Recorder : ReplyHandler
{
    std::vector<std::string> calls;
    AdminAck adminAck;
    AdmissionState admission;
    ConfigApplied configApplied;
    OrderAck orderAck;
    OrderReject orderReject;
    std::vector<OrderEvent> events;
    std::uint16_t batchCount = 0xFFFF;
    std::int64_t pageCorrelationId = 0;
    std::uint16_t pageCount = 0xFFFF;
    std::vector<std::pair<std::int64_t, OrderEvent>> pageEvents;
    OrderEventsEnd eventsEnd;
    std::uint16_t snapshotCount = 0xFFFF;
    std::vector<OrderSnapshotEntry> snapshot;
    OrderSnapshotEnd snapshotEnd;
    UserBalancesHead balancesHead;
    std::vector<std::pair<std::int64_t, BalanceLine>> lines;
    CoreConfigHead configHead;
    std::vector<MarketConfig> markets;
    std::vector<AssetConfig> assets;
    std::uint16_t updateCount = 0xFFFF;
    std::vector<BalanceUpdate> updates;
    MoneyAck depositAck;
    MoneyAck withdrawAck;
    DepositReject depositReject;
    WithdrawReject withdrawReject;

    void onAdminAck(const AdminAck &m) override { calls.push_back("AdminAck"); adminAck = m; }
    void onAdmissionState(const AdmissionState &m) override { calls.push_back("AdmissionState"); admission = m; }
    void onConfigApplied(const ConfigApplied &m) override { calls.push_back("ConfigApplied"); configApplied = m; }
    void onOrderAck(const OrderAck &m) override { calls.push_back("OrderAck"); orderAck = m; }
    void onOrderReject(const OrderReject &m) override { calls.push_back("OrderReject"); orderReject = m; }
    void onOrderEvent(const OrderEvent &m) override { calls.push_back("OrderEvent"); events.push_back(m); }
    void onOrderEventBatch(std::uint16_t n) override { calls.push_back("OrderEventBatch"); batchCount = n; }
    void onOrderEventsPage(std::int64_t c, std::uint16_t n) override
    {
        calls.push_back("OrderEventsPage");
        pageCorrelationId = c;
        pageCount = n;
    }
    void onPageEvent(std::int64_t c, const OrderEvent &m) override
    {
        calls.push_back("PageEvent");
        pageEvents.emplace_back(c, m);
    }
    void onOrderEventsEnd(const OrderEventsEnd &m) override { calls.push_back("OrderEventsEnd"); eventsEnd = m; }
    void onOrderSnapshotBatch(std::uint16_t n) override { calls.push_back("OrderSnapshotBatch"); snapshotCount = n; }
    void onOrderSnapshotEntry(const OrderSnapshotEntry &m) override
    {
        calls.push_back("OrderSnapshotEntry");
        snapshot.push_back(m);
    }
    void onOrderSnapshotEnd(const OrderSnapshotEnd &m) override { calls.push_back("OrderSnapshotEnd"); snapshotEnd = m; }
    void onUserBalances(const UserBalancesHead &m) override { calls.push_back("UserBalances"); balancesHead = m; }
    void onUserBalanceLine(std::int64_t c, const BalanceLine &m) override
    {
        calls.push_back("UserBalanceLine");
        lines.emplace_back(c, m);
    }
    void onCoreConfigReport(const CoreConfigHead &m) override { calls.push_back("CoreConfigReport"); configHead = m; }
    void onCoreConfigMarket(const MarketConfig &m) override { calls.push_back("CoreConfigMarket"); markets.push_back(m); }
    void onCoreConfigAsset(const AssetConfig &m) override { calls.push_back("CoreConfigAsset"); assets.push_back(m); }
    void onBalanceUpdate(const BalanceUpdate &m) override { calls.push_back("BalanceUpdate"); updates.push_back(m); }
    void onBalanceUpdateBatch(std::uint16_t n) override { calls.push_back("BalanceUpdateBatch"); updateCount = n; }
    void onDepositAck(const MoneyAck &m) override { calls.push_back("DepositAck"); depositAck = m; }
    void onWithdrawAck(const MoneyAck &m) override { calls.push_back("WithdrawAck"); withdrawAck = m; }
    void onDepositReject(const DepositReject &m) override { calls.push_back("DepositReject"); depositReject = m; }
    void onWithdrawReject(const WithdrawReject &m) override { calls.push_back("WithdrawReject"); withdrawReject = m; }
};

std::string joined(const std::vector<std::string> &calls)
{
    std::string out;
    for (const std::string &c : calls)
    {
        out += (out.empty() ? "" : ",") + c;
    }
    return out;
}

// Decodes a golden reply; expect() returns true when every decoded value equals the value the Java encoder wrote.
void replyCase(std::uint16_t id, const std::vector<std::uint8_t> &golden, const std::string &expectedCalls,
    const std::function<bool(const Recorder &)> &expect)
{
    covered().insert(id);
    Decoder decoder;
    Recorder recorder;
    const Refusal refusal = decoder.decode(golden.data(), golden.size(), recorder);
    if (Refusal::NONE != refusal)
    {
        gwtest::fail(__FILE__, __LINE__,
            std::string("golden mismatch ") + templateName(id) + ": " + describe(decoder.lastRefusal()));
        return;
    }
    CHECK(1 == decoder.counters().accepted && 0 == decoder.counters().refusedTotal());
    if (joined(recorder.calls) != expectedCalls)
    {
        gwtest::fail(__FILE__, __LINE__,
            std::string("golden mismatch ") + templateName(id) + ": calls " + joined(recorder.calls) + ", expected " +
                expectedCalls);
        return;
    }
    if (!expect(recorder))
    {
        gwtest::fail(__FILE__, __LINE__, std::string("golden mismatch ") + templateName(id) + ": decoded values");
    }
}

// ---- a fake client for the registrar (what CoreSessionRegistrar calls) ----
struct CapturingClient
{
    std::vector<std::uint8_t> sent;
    std::int64_t nanoTime() const { return 1; }
    cluster_tools::client::ClientState state() const { return cluster_tools::client::ClientState::CONNECTED; }
    cluster_tools::client::CloseReason closeReason() const { return cluster_tools::client::CloseReason::NONE; }
    std::uint64_t sessionEpoch() const { return 1; }
    std::int64_t leadershipTermId() const { return 0; }
    bool isConnected() const { return true; }
    cluster_tools::client::OfferResult tryOffer(const std::uint8_t *frame, std::size_t length)
    {
        sent.assign(frame, frame + length);
        cluster_tools::client::OfferResult r;
        r.status = cluster_tools::client::OfferStatus::OK;
        r.position = 64;
        return r;
    }
};

std::vector<std::uint8_t> registration(cluster_tools::client::SessionClass sessionClass, std::uint32_t channels,
    std::int64_t identity)
{
    CapturingClient client;
    cluster_tools::client::RegistrarSettings settings;
    settings.sessionClass = sessionClass;
    settings.credentialClass = sessionClass;
    settings.channels = channels;
    settings.identity = identity;
    cluster_tools::client::CoreSessionRegistrar<CapturingClient> registrar(client, settings);
    registrar.doWork();
    return client.sent;
}

}

TEST(wire_golden_corpus_is_the_pinned_core)
{
    CHECK_MSG(std::string(GOLDEN_CORE_BUILD_SHA) == GW_MONEY_SCHEMA_REF,
        std::string("gateway_frames.inc was generated from core ") + GOLDEN_CORE_BUILD_SHA +
            "; dependencies.lock pins " + GW_MONEY_SCHEMA_REF + " (tests/golden/regen.sh)");
    CHECK(GW_MONEY_SCHEMA_ID == MONEY_SCHEMA_ID);
    CHECK(GW_MONEY_SCHEMA_VERSION == MONEY_SCHEMA_VERSION);
    CHECK(8 == MONEY_SCHEMA_VERSION);
}

