void registerSessionCases()
{
    namespace ct = cluster_tools::client;
    covered().insert(tid::REGISTER_SESSION);
    const std::vector<std::uint8_t> gateway = registration(ct::SessionClass::GATEWAY,
        ct::core_channel::ACKS | ct::core_channel::CONTROL, v(80, 0, 6));
    goldenEqual("RegisterSession (oe-gateway)", JAVA_REGISTER_SESSION_GATEWAY, gateway.data(), gateway.size());
    const std::vector<std::uint8_t> stream = registration(ct::SessionClass::GATEWAY,
        ct::core_channel::ACKS | ct::core_channel::BALANCES | ct::core_channel::ORDERS | ct::core_channel::CONTROL,
        v(80, 1, 6));
    goldenEqual("RegisterSession (oe-stream)", JAVA_REGISTER_SESSION_STREAM, stream.data(), stream.size());
    const std::vector<std::uint8_t> treasury = registration(ct::SessionClass::TREASURY, ct::core_channel::ACKS,
        v(80, 2, 6));
    goldenEqual("RegisterSession (treasury lane)", JAVA_REGISTER_SESSION_TREASURY, treasury.data(), treasury.size());
}

