// Self-contained: runs every case itself, then checks that every template the gateway encodes, decodes or ignores has
// one (the result does not depend on which cases ran before, or whether any did).
TEST(wire_golden_covers_every_template)
{
    covered().clear();
    commandCases();
    registerSessionCases();
    replyCases();
    ignoredCases();
    for (const std::uint16_t id : ENCODED_TEMPLATES)
    {
        CHECK_MSG(covered().count(id), std::string("no golden case for encoded template ") + templateName(id));
    }
    for (const std::uint16_t id : DECODED_TEMPLATES)
    {
        CHECK_MSG(covered().count(id), std::string("no golden case for decoded template ") + templateName(id));
    }
    for (const std::uint16_t id : IGNORED_TEMPLATES)
    {
        CHECK_MSG(covered().count(id), std::string("no golden case for ignored template ") + templateName(id));
    }
}
